def crumbs_ld(items, B):
    """items: [(назва(укр,рос), шлях відносно кореня мови)]"""
    els = ','.join('{"@type":"ListItem","position":%d,"name":"%s","item":"{{DOMAIN}}/{{URLP}}%s"}' % (i, B(n, q="'"), path) for i, (n, path) in enumerate(items, 1))
    return _ld('{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[' + els + ']}')

def faq_ld(faq, B):
    real = [(q, a) for q, a in faq if not a[0].startswith('[')]
    if not real:
        return ''
    ents = ','.join('{"@type":"Question","name":"%s","acceptedAnswer":{"@type":"Answer","text":"%s"}}' % (B(q, q="'"), B(a, q="'")) for q, a in real)
    return _ld('{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[' + ents + ']}')

def service_ld(name, desc, B, price=None):
    off = ',"offers":{"@type":"Offer","priceCurrency":"UAH","priceSpecification":{"@type":"PriceSpecification","minPrice":%s,"priceCurrency":"UAH"}}' % price if price else ''
    return _ld('{"@context":"https://schema.org","@type":"Service","name":"%s","description":"%s","serviceType":"%s","areaServed":{"@type":"City","name":"Одеса"},'
               '"provider":{"@type":"MedicalBusiness","name":"Potapova Cosmetology","url":"{{DOMAIN}}/","telephone":"+380953231032"}%s}' % (B(name, q="'"), B(desc, q="'"), B(name, q="'"), off))

